/**
 * Placement rules for sub-issues: the tree never loops and never gets deeper
 * than `MAX_SUB_ISSUE_DEPTH`. These helpers are pure — the service gathers the
 * facts (ancestors, descendants) from storage and asks these to judge them.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export type IssueHierarchyReason = "cycle" | "too_deep";

/**
 * Raised when an issue cannot sit where it was put. `issueId` is the issue
 * whose placement was refused; for a refused creation that is the parent,
 * since the new issue has no id yet.
 */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot sit under itself or under one of its sub-issues`
        : `Issue ${issueId} would sit deeper than level ${MAX_SUB_ISSUE_DEPTH}`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** Throws when `parentId` is the issue itself or one of the issues below it. */
export function assertNotCyclic(
  issueId: string,
  parentId: string,
  below: readonly string[],
): void {
  if (parentId === issueId || below.includes(parentId)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }
}

/** Throws when the deepest issue that would result sits past the depth limit. */
export function assertWithinDepth(issueId: string, deepestLevel: number): void {
  if (deepestLevel > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

