} from "@/types/issue";
import type { Actor } from "@/types/member";

/** Open is every status that is not done or canceled. */
function isOpenStatus(status: IssueStatus): boolean {
  return !CLOSED_ISSUE_STATUSES.includes(status);
}

/**
 * Loads the parent a child is about to sit under. The parent must be a live
 * issue of the child's project; anything else is reported as not found, so
 * another project's or another workspace's issues are invisible here.
 */
async function loadPlacementParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

