  while (cursor.parentId !== null && !seen.has(cursor.parentId)) {
    seen.add(cursor.parentId);
    const parent = await issueRepo.findIssueById(orgId, cursor.parentId);
    if (parent === null) break;
    cursor = parent;
    level += 1;
  }
  return level;
}

/**
 * Tells the assignee of `closed`'s direct parent that nothing open is left
 * below it. It runs once the change is stored, so the open count it reads is
 * settled. The fan-out drops the actor's own notice. Only the direct parent
 * is considered.
 */
async function announceSubIssuesCompleted(
  actor: Actor,
  orgId: OrgId,
  closed: Issue,
): Promise<void> {
  if (closed.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, closed.parentId);
  if (parent === null || isArchived(parent) || parent.assigneeId === null) {
    return;
  }

  const below = await issueRepo.listSubtree(orgId, parent.id);
  const stillOpen = below.some(
    ({ issue }) => isLive(issue) && isOpenStatus(issue.status),
  );
  if (stillOpen) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `All sub-issues of issue ${parent.id} are closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}

