/**
 * Places an issue under a live parent of its own project, moves it under
 * another parent, or makes it a root issue again (`parentId: null`). The
 * issue's sub-issues move with it, so the depth rule is judged by where the
 * deepest of them would land. A refused placement changes nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.parentId !== null) {
    const parent = await loadPlacementParent(
      input.orgId,
      before.projectId,
      input.parentId,
    );

    const below = await issueRepo.listSubtree(input.orgId, before.id);
    assertNotCyclic(
      before.id,
      parent.id,
      below.map((node) => node.issue.id),
    );

    const deepestBelow = below.reduce(
      (deepest, node) => Math.max(deepest, node.depth),
      0,
    );
    assertWithinDepth(
      before.id,
      (await levelOf(input.orgId, parent)) + 1 + deepestBelow,
    );
  }

  if (input.parentId === before.parentId) return before;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    before.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

