): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.parentId !== null) {
    const parent = await loadPlacementParent(
      input.orgId,
      before.projectId,
      input.parentId,
    );

    const below = await issueRepo.listSubtree(input.orgId, before.id);
    assertNotCyclic(
      before.id,
      parent.id,
      below.map((node) => node.issue.id),
    );

    const deepestBelow = below.reduce(
      (deepest, node) => Math.max(deepest, node.depth),
      0,
    );
    assertWithinDepth(
      before.id,
      (await levelOf(input.orgId, parent)) + 1 + deepestBelow,
    );
  }

  if (input.parentId === before.parentId) return before;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    before.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Live direct sub-issues, oldest first. Reading needs `issue:read` on the parent. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listDirectSubIssues(orgId, issue.id);
}

/** Counts over every live issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const live = (await issueRepo.listSubtree(orgId, issue.id))
    .map((node) => node.issue)
    .filter((node) => isLive(node));
  const open = live.filter((node) => isOpenStatus(node.status)).length;

  return { total: live.length, open, closed: live.length - open };
}

