    const root = await create(tenant.actors.member, "Re-root parent");
    const child = await create(tenant.actors.member, "Re-root child", { parentId: root.id });
    const grandchild = await create(tenant.actors.member, "Re-root grandchild", {
      parentId: child.id,
    });

    const detached = await setParent(child, null);

    expect(detached.parentId).toBeNull();
    const stillBelow = await issueRepo.findIssueById(tenant.org.id, grandchild.id);
    expect(stillBelow?.parentId).toBe(child.id);
  });

  it("treats a move to the parent it already has as a no-op", async () => {
    const parent = await create(tenant.actors.member, "Same parent");
    const child = await create(tenant.actors.member, "Same parent child", {
      parentId: parent.id,
    });

    const { events } = await recording("issue.updated", () => setParent(child, parent.id));

    expect(events).toHaveLength(0);
  });

  it("refuses a parent from another project as not found", async () => {
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, secondProjectId, { title: "Other project parent" }),
    );
    const child = await create(tenant.actors.member, "Cross-project child");

    await expect(setParent(child, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a parent from another workspace as not found", async () => {
    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other workspace parent" }),
    );
    const child = await create(tenant.actors.member, "Cross-workspace child");

    await expect(setParent(child, foreign.id)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent with AlreadyArchivedError", async () => {
    const parent = await create(tenant.actors.member, "Archived parent");
    const child = await create(tenant.actors.member, "Under archived parent");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    await expect(setParent(child, parent.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses placing an issue under itself or under one of its sub-issues", async () => {
    const top = await create(tenant.actors.member, "Cycle top");
    const middle = await create(tenant.actors.member, "Cycle middle", { parentId: top.id });
    const bottom = await create(tenant.actors.member, "Cycle bottom", { parentId: middle.id });

    await expect(setParent(top, top.id)).rejects.toMatchObject({ reason: "cycle" });
    await expect(setParent(top, bottom.id)).rejects.toBeInstanceOf(IssueHierarchyError);

    const stillRoot = await issueRepo.findIssueById(tenant.org.id, top.id);
    expect(stillRoot?.parentId).toBeNull();
  });

  it("refuses a move that would leave the deepest sub-issue past the depth limit", async () => {
    const level0 = await create(tenant.actors.member, "Depth level 0");
    const level1 = await create(tenant.actors.member, "Depth level 1", { parentId: level0.id });
    const level2 = await create(tenant.actors.member, "Depth level 2", { parentId: level1.id });
    const level3 = await create(tenant.actors.member, "Depth level 3", { parentId: level2.id });

    const subtreeRoot = await create(tenant.actors.member, "Depth subtree root");
    const subtreeChild = await create(tenant.actors.member, "Depth subtree child", {
      parentId: subtreeRoot.id,
    });

    // The subtree's child would land at level 4 under level 2 — one too deep.
    await expect(setParent(subtreeRoot, level2.id)).rejects.toMatchObject({
      reason: "too_deep",
    });
    const untouched = await issueRepo.findIssueById(tenant.org.id, subtreeRoot.id);
    expect(untouched?.parentId).toBeNull();

    // Under level 1 the child lands at level 3, which is allowed.
    const moved = await setParent(subtreeRoot, level1.id);
    expect(moved.parentId).toBe(level1.id);
    const child = await issueRepo.findIssueById(tenant.org.id, subtreeChild.id);
    expect(child?.parentId).toBe(subtreeRoot.id);

    expect(level3.parentId).toBe(level2.id);
  });

  it("refuses creating a sub-issue under a parent already at the deepest level, creating nothing", async () => {
    const level0 = await create(tenant.actors.member, "Create depth 0");
    const level1 = await create(tenant.actors.member, "Create depth 1", { parentId: level0.id });
    const level2 = await create(tenant.actors.member, "Create depth 2", { parentId: level1.id });
    const level3 = await create(tenant.actors.member, "Create depth 3", { parentId: level2.id });

    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const { events } = await recording("issue.created", () =>
      create(tenant.actors.member, "Too deep to create", { parentId: level3.id }).catch(
        (error: unknown) => {
          expect(error).toMatchObject({ reason: "too_deep" });
          throw error;
        },
      ),
    ).catch(() => undefined);

    expect(events).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
  });

  it("refuses creating a sub-issue under an archived parent, creating nothing and announcing nothing", async () => {
    const parent = await create(tenant.actors.member, "Archived before create");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const { events } = await recording("issue.created", () =>
      create(tenant.actors.member, "Under archived", { parentId: parent.id }),
    ).catch((error: unknown) => ({ error, events: [] as unknown[] }));

    expect(events).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
  });

  it("refuses an archived issue being moved", async () => {
    const parent = await create(tenant.actors.member, "Move target");
    const child = await create(tenant.actors.member, "Archived mover");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    await expect(setParent(child, parent.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a viewer, who may not update issues", async () => {
    const parent = await create(tenant.actors.member, "Viewer parent");
    const child = await create(tenant.actors.member, "Viewer child");

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an orgId outside the actor's workspace", async () => {
    const parent = await create(tenant.actors.member, "Scope parent");
    const child = await create(tenant.actors.member, "Scope child");

    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: other.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — reading sub-issues", () => {
  it("lists live direct sub-issues, oldest first", async () => {
    const parent = await create(tenant.actors.member, "Listing parent");
    const first = await create(tenant.actors.member, "Listing first", { parentId: parent.id });
    const archived = await create(tenant.actors.member, "Listing archived", {
      parentId: parent.id,
    });
    const second = await create(tenant.actors.member, "Listing second", { parentId: parent.id });
    await create(tenant.actors.member, "Listing grandchild", { parentId: first.id });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const children = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      parent.id,
    );

    expect(children.map((issue) => issue.id)).toEqual([first.id, second.id]);
  });

  it("rolls up live issues at any depth into total, open and closed", async () => {
    const parent = await create(tenant.actors.member, "Rollup parent");
    const first = await create(tenant.actors.member, "Rollup first", { parentId: parent.id });
    const second = await create(tenant.actors.member, "Rollup second", { parentId: parent.id });
    const nested = await create(tenant.actors.member, "Rollup nested", { parentId: first.id });
    const archivedNested = await create(tenant.actors.member, "Rollup archived", {
      parentId: second.id,
    });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: nested.id,
      status: "canceled",
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedNested.id);

    const rollup = await issueService.getIssueRollup(
      tenant.actors.viewer,
      tenant.org.id,
      parent.id,
    );

    expect(rollup).toEqual({ total: 3, open: 1, closed: 2 });
    expect(first.id).not.toBe(second.id);
  });

  it("refuses a roll-up for an orgId outside the actor's workspace", async () => {
    const parent = await create(tenant.actors.member, "Rollup scope");

    await expect(
      issueService.getIssueRollup(tenant.actors.member, other.org.id, parent.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — archiving with sub-issues", () => {
  it("archives every live issue below, announcing each once and leaving earlier archives alone", async () => {
    const parent = await create(tenant.actors.member, "Cascade parent");
    const child = await create(tenant.actors.member, "Cascade child", { parentId: parent.id });
    const grandchild = await create(tenant.actors.member, "Cascade grandchild", {
      parentId: child.id,
    });
    const earlier = await create(tenant.actors.member, "Cascade earlier", { parentId: parent.id });
    const earlierArchive = await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      earlier.id,
    );

    const { events } = await recording("issue.archived", () =>
      issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id),
    );

    const announced = events.map((event) => (event as { issueId: IssueId }).issueId);
    expect(announced.sort()).toEqual([parent.id, child.id, grandchild.id].sort());

    const stillArchived = await issueRepo.findIssueById(tenant.org.id, earlier.id);
    expect(stillArchived?.archivedAt).toBe(earlierArchive.archivedAt);
  });

  it("archiving a sub-issue leaves its parent live", async () => {
    const parent = await create(tenant.actors.member, "Sub-archive parent");
    const child = await create(tenant.actors.member, "Sub-archive child", { parentId: parent.id });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    const stillLive = await issueRepo.findIssueById(tenant.org.id, parent.id);
    expect(stillLive?.archivedAt).toBeNull();
  });
});

describe("services/issue-service — sub-issue completion notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue closes", async () => {
    const parent = await create(tenant.actors.member, "Notice parent", {
      assigneeId: tenant.userIds.admin,
    });
    const first = await create(tenant.actors.member, "Notice first", { parentId: parent.id });
    const second = await create(tenant.actors.member, "Notice second", { parentId: parent.id });
    const recipients = [tenant.userIds.admin];

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "done",
    });
    expect(await noticesFor(parent.id, recipients)).toBe(0);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "canceled",
    });
    expect(await noticesFor(parent.id, recipients)).toBe(1);

    // Closed to another closed status is not a closing.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      status: "done",
    });
    expect(await noticesFor(parent.id, recipients)).toBe(1);

    // Reopening and closing again tells the assignee again.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "done",
    });
    expect(await noticesFor(parent.id, recipients)).toBe(2);
  });

  it("does not tell the actor about their own change", async () => {
    const parent = await create(tenant.actors.member, "Self notice parent", {
      assigneeId: tenant.userIds.member,
    });
    const child = await create(tenant.actors.member, "Self notice child", { parentId: parent.id });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child.id,
      status: "done",
    });

    expect(await noticesFor(parent.id, [tenant.userIds.member])).toBe(0);
  });

  it("tells the assignee when the last open sub-issue is archived", async () => {
    const parent = await create(tenant.actors.member, "Archive notice parent", {
      assigneeId: tenant.userIds.admin,
    });
    const child = await create(tenant.actors.member, "Archive notice child", {
      parentId: parent.id,
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect(await noticesFor(parent.id, [tenant.userIds.admin])).toBe(1);
  });

  it("sends nothing when the parent has no assignee, or when the parent itself is archived", async () => {
    const unassigned = await create(tenant.actors.member, "Unassigned parent");
    const unassignedChild = await create(tenant.actors.member, "Unassigned child", {
      parentId: unassigned.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: unassignedChild.id,
      status: "done",
    });
    expect(await noticesFor(unassigned.id, EVERYONE.concat(tenant.userIds.admin))).toBe(0);

    const archivedParent = await create(tenant.actors.member, "Archived-together parent", {
      assigneeId: tenant.userIds.admin,
    });
    await create(tenant.actors.member, "Archived-together child", {
      parentId: archivedParent.id,
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedParent.id);
    expect(await noticesFor(archivedParent.id, [tenant.userIds.admin])).toBe(0);
  });
});

